import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Altezze, mediane e triangolo isoscele","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fe/fed.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fe/fed.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fe/fed.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="altezze-mediane-e-triangolo-isoscele" tabindex="-1">Altezze, mediane e triangolo isoscele <a class="header-anchor" href="#altezze-mediane-e-triangolo-isoscele" aria-label="Permalink to “Altezze, mediane e triangolo isoscele”">​</a></h1><p>Qui vediamo alcune definizioni ed anche una proprietà notevole del triangolo isoscele:</p><blockquote><p class="text-blue">[Definiamo altezza di un triangolo il segmento di perpendicolare condotto da un vertice al lato opposto]</p><p>In figura <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>H</mi></mrow><annotation encoding="application/x-tex">AH</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> è un&#39;altezza</p></blockquote><p>Naturalmente nel triangolo vi saranno <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> altezze.</p><blockquote><p class="text-blue">[Definiamo mediana il segmento congiungente il vertice di un triangolo con il punto medio del lato opposto]</p><p>In figura <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>M</mi></mrow><annotation encoding="application/x-tex">AM</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> è una mediana</p></blockquote><p>Anche di mediane ogni triangolo ne possiede <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span>.</p><p>Date queste definizioni possiamo dire che vale:</p><p class="text-blue">[In un triangolo isoscele l&#39;altezza, la mediana e la bisettrice condotte dal vertice opposto alla base sono coincidenti]</p><p>Per esercizio fai la dimostrazione.</p><p>E vale anche l&#39;inverso:</p><p class="text-blue">[Se in un triangolo l&#39;altezza, la mediana e la bisettrice condotte dal vertice opposto alla base sono coincidenti allora il triangolo è isoscele]</p><p>Per esercizio fai la dimostrazione.</p><p>Siccome abbiamo un teorema ed anche il suo inverso, d&#39;ora in avanti i fatti:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mtext>triangolo\xA0isoscele</mtext><mtext>  </mtext><mo>⟺</mo><mtext>  </mtext><mtext>altezza</mtext><mo>=</mo><mtext>mediana</mtext><mo>=</mo><mtext>bisettrice</mtext></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{triangolo isoscele} \\iff \\text{altezza} = \\text{mediana} = \\text{bisettrice}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">triangolo\xA0isoscele</span></span><span class="mspace" style="color:red;margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">⟺</span><span class="mspace" style="color:red;margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">altezza</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">mediana</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">bisettrice</span></span></span></span></span></span></p><p>saranno equivalenti.</p><p>Naturalmente ciò vale solamente per il vertice e la base di un triangolo isoscele: negli altri due lati l&#39;altezza, la mediana e la bisettrice saranno <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> segmenti diversi.</p><p>In figura:</p><ul><li>altezze in nero</li><li class="text-red">[mediane in rosso]</li><li class="text-blue">[bisettrici in blu]</li></ul>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};